-- Group, DENY, share-grant and MSCK PRIVILEGES statements.
CREATE GROUP g;

CREATE GROUP g WITH USER `u`;

CREATE GROUP g WITH USER `u` GROUP h;

DROP GROUP g;

DENY SELECT ON TABLE t TO `u`;

DENY ALL PRIVILEGES ON TABLE t TO `u`;

GRANT SELECT ON SHARE s TO RECIPIENT r;

REVOKE SELECT ON SHARE s FROM RECIPIENT r;

GRANT READ FILES ON ANY FILE TO `u`;

MSCK REPAIR SCHEMA s PRIVILEGES;

MSCK REPAIR TABLE t PRIVILEGES;

MSCK REPAIR ANONYMOUS FUNCTION PRIVILEGES;
